<template>
    <div class="auth-page">
      <!-- 桌面端左侧插画区域 -->
      <div class="auth-illustration">
        <svg viewBox="0 0 400 400" xmlns="http://www.w3.org/2000/svg">
          <!-- 眼科相关SVG插画 -->
          <circle cx="200" cy="200" r="150" fill="#F8F9FA" />
          <circle cx="200" cy="200" r="100" fill="white" />
          <circle cx="200" cy="200" r="30" fill="#3A6FAC" />
          <circle cx="200" cy="200" r="15" fill="#5BA291" />
          
          <text x="50%" y="90%" text-anchor="middle" font-size="14" fill="white">
            眼科智能诊断系统
          </text>
        </svg>
      </div>
      
      <!-- 右侧表单区域 -->
      <div class="auth-form-container">
        <div class="auth-card">
          <div class="auth-header">
            <h1>眼科智能诊断系统</h1>
            <p>专业的眼科疾病诊断与辅助工具</p>
          </div>
          
          <!-- 登录/注册切换标签 -->
          <div class="auth-tabs">
            <div 
              class="auth-tab" 
              :class="{ active: currentTab === 'login' }"
              @click="currentTab = 'login'"
            >
              登录
            </div>
            <div 
              class="auth-tab" 
              :class="{ active: currentTab === 'register' }"
              @click="currentTab = 'register'"
            >
              注册
            </div>
          </div>
          
          <!-- 表单内容 -->
          <div v-if="currentTab === 'login'">
            <form @submit.prevent="handleLogin">
              <div class="form-group">
                <input
                  type="email"
                  class="form-control"
                  placeholder="电子邮箱"
                  v-model="loginForm.email"
                  @blur="validateLoginEmail"
                >
                <div class="error-message" :class="{ visible: loginEmailError }">
                  {{ loginEmailError }}
                </div>
              </div>
              
              <div class="form-group password-toggle">
                <input
                  :type="showPassword ? 'text' : 'password'"
                  class="form-control"
                  placeholder="密码"
                  v-model="loginForm.password"
                >
                <button 
                  type="button" 
                  class="password-toggle-button"
                  @click="showPassword = !showPassword"
                >
                  <svg v-if="showPassword" width="16" height="16" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
                  </svg>
                  <svg v-else width="16" height="16" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
                    <path d="M12 12c2.1 0 4.07.85 5.3 2.16" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
                  </svg>
                </button>
              </div>
              
              <div class="form-group captcha-container">
                <input
                  type="text"
                  class="captcha-input form-control"
                  placeholder="验证码"
                  v-model="loginForm.captcha"
                >
                <div class="captcha-image" @click="refreshCaptcha">
                  <svg width="100" height="46" viewBox="0 0 100 46" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <rect width="100" height="46" rx="4" fill="#F8F9FA" />
                    <text x="50%" y="60%" text-anchor="middle" font-size="24" fill="#3A6FAC">YZ72</text>
                  </svg>
                </div>
              </div>
              
              <div class="form-group">
                <button type="submit" class="btn btn-primary" :disabled="loginLoading">
                  <span v-if="loginLoading">
                    <div class="loading-spinner"></div>
                  </span>
                  <span v-else>登录</span>
                </button>
              </div>
              
              <div class="auth-footer">
                忘记密码? <a href="#">重置密码</a>
              </div>
            </form>
          </div>
          
          <div v-else>
            <form @submit.prevent="handleRegister">
              <div class="form-group">
                <input
                  type="text"
                  class="form-control"
                  placeholder="真实姓名"
                  v-model="registerForm.name"
                >
              </div>
              
              <div class="form-group">
                <input
                  type="email"
                  class="form-control"
                  placeholder="电子邮箱"
                  v-model="registerForm.email"
                  @blur="validateRegisterEmail"
                >
                <div class="error-message" :class="{ visible: registerEmailError }">
                  {{ registerEmailError }}
                </div>
              </div>
              
              <div class="form-group">
                <input
                  type="tel"
                  class="form-control"
                  placeholder="手机号码"
                  v-model="registerForm.phone"
                  @blur="validatePhone"
                >
                <div class="error-message" :class="{ visible: phoneError }">
                  {{ phoneError }}
                </div>
              </div>
              
              <div class="form-group password-toggle">
                <input
                  :type="showPassword ? 'text' : 'password'"
                  class="form-control"
                  placeholder="创建密码"
                  v-model="registerForm.password"
                  @input="updatePasswordStrength"
                >
                <button 
                  type="button" 
                  class="password-toggle-button"
                  @click="showPassword = !showPassword"
                >
                  <svg v-if="showPassword" width="16" height="16" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
                  </svg>
                  <svg v-else width="16" height="16" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
                    <path d="M12 12c2.1 0 4.07.85 5.3 2.16" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
                  </svg>
                </button>
              </div>
              
              <div class="password-strength">
                <div class="strength-bar" :class="'strength-' + passwordStrength" :style="{ width: passwordStrength * 25 + '%' }"></div>
              </div>
              
              <div class="form-group password-toggle">
                <input
                  :type="showConfirmPassword ? 'text' : 'password'"
                  class="form-control"
                  placeholder="确认密码"
                  v-model="registerForm.confirmPassword"
                  @input="validatePasswordsMatch"
                >
                <button 
                  type="button" 
                  class="password-toggle-button"
                  @click="showConfirmPassword = !showConfirmPassword"
                >
                  <svg v-if="showConfirmPassword" width="16" height="16" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
                  </svg>
                  <svg v-else width="16" height="16" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
                    <path d="M12 12c2.1 0 4.07.85 5.3 2.16" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
                  </svg>
                </button>
              </div>
              
              <div class="form-group captcha-container">
                <input
                  type="text"
                  class="captcha-input form-control"
                  placeholder="验证码"
                  v-model="registerForm.captcha"
                >
                <div class="captcha-image" @click="refreshCaptcha">
                  <svg width="100" height="46" viewBox="0 0 100 46" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <rect width="100" height="46" rx="4" fill="#F8F9FA" />
                    <text x="50%" y="60%" text-anchor="middle" font-size="24" fill="#3A6FAC">YZ72</text>
                  </svg>
                </div>
              </div>
              
              <div class="form-group">
                <button type="submit" class="btn btn-primary" :disabled="registerLoading">
                  <span v-if="registerLoading">
                    <div class="loading-spinner"></div>
                  </span>
                  <span v-else>注册</span>
                </button>
              </div>
              
              <div class="auth-footer">
                注册即表示您同意我们的<a href="#">服务条款</a>和<a href="#">隐私政策</a>
              </div>
            </form>
          </div>
          
          <!-- 成功勾选动画 -->
          <div class="checkmark" :class="{ visible: showCheckmark }"></div>
        </div>
      </div>
      
      <!-- 高对比度模式开关 -->
      <div class="high-contrast-toggle" @click="toggleHighContrast">
        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
          <rect width="24" height="24" fill="none"/>
          <circle cx="12" cy="12" r="10" stroke="currentColor" stroke-width="2"/>
          <path d="M12 8v8" stroke="currentColor" stroke-width="2"/>
          <path d="M8 12h8" stroke="currentColor" stroke-width="2"/>
        </svg>
        高对比度
      </div>
      
      <!-- 低视力模式按钮 -->
      <button class="low-vision-mode" @click="toggleLowVisionMode">
        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
          <circle cx="12" cy="12" r="10" stroke="white" stroke-width="2"/>
          <circle cx="12" cy="12" r="4" fill="white"/>
        </svg>
      </button>
    </div>
  </template>
  
  <script>
  export default {
    name:'UserLogin',
    data() {
      return {
        currentTab: 'login',
        showPassword: false,
        showConfirmPassword: false,
        loginLoading: false,
        registerLoading: false,
        showCheckmark: false,
        highContrast: false,
        lowVisionMode: false,
        
        // 登录表单
        loginForm: {
          email: '',
          password: '',
          captcha: ''
        },
        loginEmailError: '',
        
        // 注册表单
        registerForm: {
          name: '',
          email: '',
          phone: '',
          password: '',
          confirmPassword: '',
          captcha: ''
        },
        registerEmailError: '',
        phoneError: '',
        passwordStrength: 0
      };
    },
    methods: {
      // 登录处理
      handleLogin() {
        this.loginLoading = true;
        // 模拟API请求
        setTimeout(() => {
          this.loginLoading = false;
          this.showCheckmark = true;
          
          // 1秒后重置勾选动画
          setTimeout(() => {
            this.showCheckmark = false;
          }, 1000);
          
          // 实际应用中这里应该是真实的API调用
          console.log('登录成功:', this.loginForm);
        }, 1500);
      },
      
      // 注册处理
      handleRegister() {
        this.registerLoading = true;
        // 模拟API请求
        setTimeout(() => {
          this.registerLoading = false;
          this.showCheckmark = true;
          
          // 1秒后重置勾选动画
          setTimeout(() => {
            this.showCheckmark = false;
          }, 1000);
          
          // 实际应用中这里应该是真实的API调用
          console.log('注册成功:', this.registerForm);
        }, 1500);
      },
      
      // 验证登录邮箱
      validateLoginEmail() {
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!this.loginForm.email) {
          this.loginEmailError = '请输入电子邮箱';
        } else if (!emailRegex.test(this.loginForm.email)) {
          this.loginEmailError = '请输入有效的电子邮箱地址';
        } else {
          this.loginEmailError = '';
        }
      },
      
      // 验证注册邮箱
      validateRegisterEmail() {
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!this.registerForm.email) {
          this.registerEmailError = '请输入电子邮箱';
        } else if (!emailRegex.test(this.registerForm.email)) {
          this.registerEmailError = '请输入有效的电子邮箱地址';
        } else {
          this.registerEmailError = '';
        }
      },
      
      // 验证手机号码
      validatePhone() {
        const phoneRegex = /^1[3-9]\d{9}$/; // 简单的中国手机号验证
        if (!this.registerForm.phone) {
          this.phoneError = '请输入手机号码';
        } else if (!phoneRegex.test(this.registerForm.phone)) {
          this.phoneError = '请输入有效的手机号码';
        } else {
          this.phoneError = '';
        }
      },
      
      // 更新密码强度
      updatePasswordStrength() {
        const password = this.registerForm.password;
        let strength = 0;
        
        // 至少6个字符
        if (password.length >= 6) strength = 1;
        
        // 包含数字和字母
        if (/[A-Za-z]/.test(password) && /\d/.test(password)) strength = 2;
        
        // 包含特殊字符
        if (/[^A-Za-z\d]/.test(password)) strength = 3;
        
        // 至少10个字符
        if (password.length >= 10) strength = 4;
        
        this.passwordStrength = strength;
      },
      
      // 验证密码是否匹配
      validatePasswordsMatch() {
        if (this.registerForm.password !== this.registerForm.confirmPassword) {
          // 这里没有显示错误信息，实际应用中应该添加
          console.log('密码不匹配');
        }
      },
      
      // 刷新验证码
      refreshCaptcha() {
        console.log('刷新验证码');
        // 实际应用中这里应该是请求新的验证码图片
      },
      
      // 切换高对比度模式
      toggleHighContrast() {
        this.highContrast = !this.highContrast;
        if (this.highContrast) {
          document.body.style.filter = 'contrast(120%)';
        } else {
          document.body.style.filter = 'none';
        }
      },
      
      // 切换低视力模式
      toggleLowVisionMode() {
        this.lowVisionMode = !this.lowVisionMode;
        if (this.lowVisionMode) {
          document.body.style.filter = 'contrast(150%) brightness(120%)';
          document.body.style.backgroundColor = '#000';
          document.body.style.color = '#fff';
        } else {
          document.body.style.filter = 'none';
          document.body.style.backgroundColor = '';
          document.body.style.color = '';
        }
      }
    }
  };
  </script>
  
  <style>
  @import '@/assets/css/login.css';
  </style>