<template>
  <div class="app-container">
    
    
    <!-- 智能抽屉式侧边栏 -->
    <aside
      class="drawer-sidebar"
      :class="{ 'drawer-open': isDrawerOpen }"
      @mouseenter="handleDrawerMouseEnter"
      @mouseleave="handleDrawerMouseLeave"
    >
      <!-- 侧边栏内容 -->
      <div class="drawer-content">
        <div class="logo-container">
          <router-link to="/">
            <img src="@/assets/images/logo.png" alt="Logo">
            <h1 v-if="!isDrawerCollapsed">眼科疾病智能诊断系统</h1>
          </router-link>
        </div>
        <nav class="drawer-nav">
          <ul>
            <li><router-link to="/">首页</router-link></li>
            <li><router-link to="/detection">疾病识别</router-link></li>
            <li><router-link to="/assistant">眼科智能助手</router-link></li>
            <li><router-link to="/library">眼底图片库</router-link></li>
            <li><router-link to="/data-analysis">数据分析</router-link></li>
            <li><router-link to="/vision">未来展望</router-link></li>
            <li><router-link to="/aboutview">关于我们</router-link></li>
          </ul>
        </nav>
        <div class="user-profile" @click.stop="toggleDropdown">
          <div class="avatar-container">
            <img src="@/assets/images/avatar.png" alt="User Avatar" class="avatar">
            <span class="avatar-text" v-if="!isDrawerCollapsed">用户头像</span>
          </div>
          <div class="dropdown-menu" v-if="isDropdownVisible">
            <div class="user-role">用户角色</div>
            <div class="user-info">个人信息</div>
            <div class="logout">退出登录</div>
          </div>
        </div>
      </div>
      
      <!-- 抽屉控制按钮 -->
      <button class="drawer-toggle" @click="toggleDrawer">
        <span class="toggle-icon"></span>
      </button>
    </aside>
  </div>
</template>

<script>
export default {
  name: 'App',
  data() {
    return {
      isDrawerOpen: false,
      isDrawerCollapsed: true,
      isDropdownVisible: false,
      mouseNearLeftEdge: false,
      mouseInDrawer: false
    };
  },
  methods: {
    toggleDropdown() {
      this.isDropdownVisible = !this.isDropdownVisible;
    },
    closeDropdownOnOutsideClick(event) {
      const dropdown = this.$el.querySelector('.dropdown-menu');
      if (
        dropdown &&
        !dropdown.contains(event.target) &&
        !this.$el.querySelector('.user-profile').contains(event.target)
      ) {
        this.isDropdownVisible = false;
      }
    },
    toggleDrawer() {
      this.isDrawerOpen = !this.isDrawerOpen;
      this.isDrawerCollapsed = !this.isDrawerCollapsed;
    },
    handleWindowScroll() {
      if (this.isDrawerOpen && !this.mouseInDrawer) {
        this.isDrawerOpen = false;
        this.isDrawerCollapsed = true;
      }
    },
    handleMouseMove(event) {
      const leftEdgeThreshold = 10; // 左边缘10px范围
      if (event.clientX <= leftEdgeThreshold) {
        if (!this.mouseNearLeftEdge && !this.mouseInDrawer) {
          this.mouseNearLeftEdge = true;
          this.isDrawerOpen = true;
          this.isDrawerCollapsed = false;
        }
      } else {
        if (this.mouseNearLeftEdge && !this.mouseInDrawer) {
          this.mouseNearLeftEdge = false;
          this.isDrawerOpen = false;
          this.isDrawerCollapsed = true;
        }
      }
    },
    handleDrawerMouseEnter() {
      this.mouseInDrawer = true;
      this.isDrawerOpen = true;
      this.isDrawerCollapsed = false;
    },
    handleDrawerMouseLeave() {
      this.mouseInDrawer = false;
      this.isDrawerOpen = false;
      this.isDrawerCollapsed = true;
    }
  },
  mounted() {
    document.addEventListener('click', this.closeDropdownOnOutsideClick);
    window.addEventListener('scroll', this.handleWindowScroll);
    window.addEventListener('mousemove', this.handleMouseMove);
  },
  beforeDestroy() {
    document.removeEventListener('click', this.closeDropdownOnOutsideClick);
    window.removeEventListener('scroll', this.handleWindowScroll);
    window.removeEventListener('mousemove', this.handleMouseMove);
  }
};
</script>

<style scoped>
@import '@/assets/css/header.css';
</style>