<template>
  <div id="app" class="home">
    <main>
      <section class="hero">
        <h1>眼科疾病智能诊断系统</h1>
        <p>利用先进的人工智能技术，为眼科疾病提供精准诊断</p>
      </section>
      
      <section class="main-visual">
        <div class="video-container">
          <!-- 使用静态图片替代视频 -->
          <div class="placeholder-animation">
            <div class="eye-examination-steps">
              <div class="step">
                <div class="step-number">1</div>
                <div class="step-description">上传眼底影像</div>
              </div>
              <div class="step">
                <div class="step-number">2</div>
                <div class="step-description">AI实时分析</div>
              </div>
              <div class="step">
                <div class="step-number">3</div>
                <div class="step-description">生成诊断报告</div>
              </div>
            </div>
            <div class="video-overlay">
              <h2>AI赋能精准眼科，1秒筛查高危病变</h2>
            </div>
          </div>
          <div class="data-board">
            <div class="data-item">
              <span class="data-label">模型准确率：</span>
              <span class="data-value">96.3%</span>
            </div>
            <div class="data-item">
              <span class="data-label">已筛查病例：</span>
              <span class="data-value" ref="case-count">50,000+</span>
            </div>
            <div class="data-item">
              <span class="data-label">合作医院：</span>
              <span class="data-value">120家</span>
            </div>
          </div>
        </div>
      </section>

      <section class="features">
        <div class="feature">
          <h3>眼科疾病</h3>
          <p>疾病种类</p>
        </div>
        <div class="feature">
          <h3>青光眼</h3>
          <p>病情展示</p>
        </div>
        <div class="feature">
          <h3>白内障</h3>
          <p>常见症状</p>
        </div>
      </section>
    </main>
    <!-- AI助手入口 -->
    <div class="ai-assistant" @click="goToAssistant" @mouseover="mouseOver" @mouseout="mouseOut">
      <div class="ai-assistant-ball">
        <div class="ai-chip"></div>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: 'HomeView',
  data() {
    return {
      caseCount: 50000,
      isHovered: false,
      isClicked: false,
      hasNewMessage: false
    };
  },
  methods: {
    goToAssistant() {
      console.log('AI助手点击事件触发');
      this.$router.push('/assistant');
    },
    mouseOver() {
      this.isHovered = true;
    },
    mouseOut() {
      this.isHovered = false;
    },
    updateCaseCount() {
      this.caseCount += 10;
      if (this.$refs['case-count']) {
        this.$refs['case-count'].textContent = this.caseCount.toLocaleString() + '+';
      }
    }
  },
  mounted() {
    // 动态更新已筛查病例数
    setInterval(this.updateCaseCount, 1000);
  }
};
</script>

<style scoped>
